    applyManagedBounds(id,bounds,clip=true){const win=this.windows.find(w=>w.id===id);if(!win||!bounds)return;const system=this.systems.get(win.systemId);Object.assign(win,{x:Number(bounds.x),y:Number(bounds.y),width:Number(bounds.width),height:Number(bounds.height)});if(clip){win.width=N.clamp(win.width,280,system.desktop.clientWidth);win.height=N.clamp(win.height,190,system.desktop.clientHeight);win.x=N.clamp(win.x,-win.width+120,system.desktop.clientWidth-80);win.y=N.clamp(win.y,0,system.desktop.clientHeight-90);}this.layoutWindow(win);}
